import React, {
  MouseEventHandler,
  PropsWithChildren,
  ReactElement,
  ReactNode,
  useState,
} from "react";
import clsx from "clsx";
import { Chip as ChipStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";

type Props = PropsWithChildren<{
  /** If true, the chip will appear clickable. */
  clickable?: boolean;
  /** An icon to display. */
  icon?: ReactElement;
  /** The label of the `Chip`. */
  label?: string | ReactNode;
  /** Callback function fired when the delete button is clicked. If set, the delete button will be shown. */
  onDelete?: MouseEventHandler<HTMLButtonElement>;
  /** Callback function fired when the chip is clicked. If set, the chip will appear clickable. */
  onClick?: MouseEventHandler<HTMLDivElement>;
  /**
   * The size of the chip.
   * @default small
   */
  size?: "medium" | "small" | "xsmall";
  /**
   * The variant of the chip.
   * @default default
   */
  variant?: "default" | "info" | "success" | "warning" | "error";
}>;

export type ChipProps = Props & CommonProps;

const useStyles = createUseStyles(ChipStyles, "chip");

const DeleteButton = ({
  onClick,
}: {
  onClick: MouseEventHandler<HTMLButtonElement>;
}) => {
  const classes = useStyles();
  return (
    <button
      type="button"
      className={classes.removeBtn}
      aria-label="Remove"
      onClick={onClick}
      onTouchEnd={(e: any) => {
        e.preventDefault();
        onClick && onClick(e);
      }}
      onMouseDown={(e) => {
        e.preventDefault();
        e.stopPropagation();
      }}
    />
  );
};

const Chip = (props: ChipProps) => {
  const {
    className,
    label,
    children,
    icon,
    onDelete,
    onClick,
    clickable,
    variant = "default",
    size = "small",
    ...rest
  } = props;
  const classes = useStyles();
  const [active, setActive] = useState(false);

  // For Keyboard accessibility - triggered onClick with Space or Enter
  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if ((clickable || onClick) && (e.key === " " || e.key === "Enter")) {
      setActive(true);
      e.preventDefault();
      onClick && onClick(e as any);
    }
  };

  const handleKeyUp = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if ((clickable || onClick) && (e.key === " " || e.key === "Enter")) {
      setActive(false);
    }
  };
  // remove active state on blur
  const handleBlur = () => {
    setActive(false);
  };

  return (
    <div
      role={clickable || onClick ? "button" : undefined}
      tabIndex={clickable || onClick ? 0 : undefined}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      onKeyUp={handleKeyUp}
      onBlur={handleBlur}
      className={clsx(
        className,
        classes.root,
        (clickable || onClick) && classes._clickable,
        active && classes._active,
        variant !== "default" && classes[`_${variant}`],
        size !== "small" && classes[`_${size}`]
      )}
      {...rest}
    >
      {icon && <span className={classes.icon}>{icon}</span>}
      <span className={classes.label}>{label || children}</span>
      {onDelete && <DeleteButton onClick={onDelete} />}
    </div>
  );
};

export default Chip;
